function solve({config,state,event}){
 const M=config.maxBytes;
 if(state===null)state={v:{},t:null,b:[],x:false,e:0};
 const fail=()=>{state.e++;state.t=null};
 function utf(a){let s='';for(let i=0;i<a.length;){let c=a[i++],n=0,min=0;if(c<128){s+=String.fromCharCode(c);continue}if(c>=194&&c<=223){n=1;min=128;c&=31}else if(c>=224&&c<=239){n=2;min=2048;c&=15}else if(c>=240&&c<=244){n=3;min=65536;c&=7}else return null;let q=c;for(let j=0;j<n;j++){if(i>=a.length||(a[i]&192)!==128)return null;q=q*64+(a[i++]&63)}if(q<min||q>1114111||(q>=55296&&q<=57343))return null;s+=String.fromCodePoint(q)}return s}
 const scalar=x=>x===null||typeof x==='string'&&!/[\uD800-\uDFFF]/.test(x)||typeof x==='boolean'||typeof x==='number'&&Number.isSafeInteger(x);
 const exact=(o,ks)=>{if(!o||typeof o!=='object'||Array.isArray(o))return false;let z=Object.keys(o);return z.length===ks.length&&ks.every(k=>Object.prototype.hasOwnProperty.call(o,k))};
 function frame(a){let s=utf(a),o;if(s===null){fail();return}try{o=JSON.parse(s)}catch(_){fail();return}
  let ok=false;
  if(exact(o,['op','id'])&&o.op==='begin'&&typeof o.id==='string'&&!/[\uD800-\uDFFF]/.test(o.id))ok=1;
  else if(exact(o,['op','key','value'])&&o.op==='put'&&typeof o.key==='string'&&!/[\uD800-\uDFFF]/.test(o.key)&&scalar(o.value))ok=1;
  else if(exact(o,['op','id'])&&o.op==='commit'&&typeof o.id==='string'&&!/[\uD800-\uDFFF]/.test(o.id))ok=1;
  else if(exact(o,['op'])&&o.op==='abort')ok=1;
  if(!ok){fail();return}
  if(o.op==='begin'){if(state.t)fail();else state.t={i:o.id,d:Object.assign({},state.v)}}
  else if(o.op==='put'){if(!state.t)fail();else state.t.d[o.key]=o.value}
  else if(o.op==='commit'){if(!state.t||state.t.i!==o.id)fail();else{state.v=state.t.d;state.t=null}}
  else state.t=null;
 }
 if(event.type==='chunk')for(let i=0;i<event.bytes.length;i++){let n=event.bytes[i];if(state.x){if(n===10)state.x=false;continue}if(n===10){frame(state.b);state.b=[]}else{state.b.push(n);if(state.b.length>M){state.e++;state.t=null;state.b=[];state.x=true}}}
 else if(event.type==='finish'){if(state.x)state.x=false;else if(state.b.length){state.e++;state.b=[]}if(state.t){state.e++;state.t=null}}
 return {state,output:{visible:state.v,open:state.t?state.t.i:null,buffered:state.b.length,errors:state.e}};
}
